namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class catbox extends cloudStorage2 { var $host = 'catbox.moe'; public function init() { $this->silent_scanning = $this->options->cloud_storage_catbox_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_catbox_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $name = basename($source_path); preg_match('/(.*?)\\.[A-Za-z0-9]+/', $name,$m); $name=$m[0]; $type = mime_content_type($source_path); $bits = file_get_contents($source_path); $target_url = 'https://catbox.moe/user/api.php'; $data = array(); $mimeBoundary = '----WebKitFormBoundary' . uniqid(); array_push($data, '--' . $mimeBoundary); $mimeType = empty($type) ? 'application/octet-stream' : $type; array_push($data, 'Content-Disposition: form-data; name="reqtype"'); array_push($data, ''); array_push($data, 'fileupload'); array_push($data, '--' . $mimeBoundary); array_push($data, 'Content-Disposition: form-data; name="userhash"'); array_push($data, ''); array_push($data, ''); array_push($data, "Content-Disposition: form-data; name=\"fileToUpload\"; filename=\"$name\""); array_push($data, "Content-Type: $mimeType"); array_push($data, ''); array_push($data, $bits); array_push($data, '--' . $mimeBoundary . "--"); $post_data = implode("\r\n", $data); $length = strlen($post_data); $headers = array(); array_push($headers, ':authority: catbox.moe'); array_push($headers, ':method: POST'); array_push($headers, ':path: /user/api.php'); array_push($headers, ':scheme: https'); array_push($headers, "accept: application/json"); array_push($headers, "accept-encoding: gzip, deflate, br"); array_push($headers, "accept-language: zh-CN,zh;q=0.9,zh-TW;q=0.8,en;q=0.7,en-US;q=0.6,und;q=0.5"); array_push($headers, "cache-control: no-cache"); array_push($headers, "content-length: {$length}"); array_push($headers, "content-type: multipart/form-data; boundary={$mimeBoundary}"); array_push($headers, "origin: https://nofun.catbox.moe"); array_push($headers, "referer: https://nofun.catbox.moe/"); array_push($headers, "user-agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/74.0.3729.131 Safari/537.36"); array_push($headers, "x-requested-with: XMLHttpRequest"); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $target_url); curl_setopt($ch, CURLOPT_HTTPHEADER, $headers); curl_setopt($ch, CURLOPT_USERAGENT, $this->user_agent); curl_setopt($ch, CURLOPT_POST, 1); curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false); curl_setopt($ch, CURLOPT_REFERER, 'https://nofun.catbox.moe/'); $result = curl_exec($ch); curl_close($ch); $result = gzdecode($result); if ($result) { return $result; } else { do_action( 'qqworld-collector-log', $this->log_id, 'catbox failed: ', print_r($result, true) ); } return false; } } ?>